{"status": 200, "headers": {"Accept-Ranges": "bytes", "Content-Length": "12193", "Content-Type": "text/css; charset=utf-8", "Last-Modified": "Sat, 18 Apr 2026 15:52:24 GMT", "Date": "Tue, 28 Apr 2026 19:52:27 GMT"}, "body": "/* Greystone Gazette, PressRoom editorial system.
   Durham-purple newspaper theme. Clean, dense, slightly dated. */

:root {
  --gz-purple: #68246d;
  --gz-purple-dark: #431849;
  --gz-purple-light: #8a3f91;
  --gz-accent: #ad8ab2;
  --gz-ink: #1a1620;
  --gz-paper: #fbf9f6;
  --gz-rule: #d7cfda;
  --gz-muted: #6b5f6f;
  --gz-warn: #8a5a00;
  --gz-warn-bg: #fff5e0;
  --gz-error: #8b1f29;
  --gz-error-bg: #fbe8ea;
}

* {
  box-sizing: border-box;
}

html, body {
  margin: 0;
  padding: 0;
  background: var(--gz-paper);
  color: var(--gz-ink);
  font-family: "Georgia", "Times New Roman", serif;
  font-size: 16px;
  line-height: 1.55;
}

a {
  color: var(--gz-purple);
  text-decoration: none;
}
a:hover {
  text-decoration: underline;
}

code {
  font-family: "Menlo", "Consolas", "Courier New", monospace;
  background: #efeaf0;
  color: var(--gz-purple-dark);
  padding: 1px 4px;
  border-radius: 2px;
  font-size: 0.92em;
}

pre {
  background: #efeaf0;
  color: var(--gz-purple-dark);
  font-family: "Menlo", "Consolas", "Courier New", monospace;
  padding: 10px 12px;
  border-radius: 3px;
  overflow-x: auto;
  font-size: 0.9em;
}

/* Header / masthead */
.site-header {
  background: var(--gz-purple);
  color: var(--gz-paper);
  border-bottom: 4px solid var(--gz-purple-dark);
  padding: 14px 28px 8px 28px;
}
.masthead {
  display: flex;
  align-items: baseline;
  gap: 16px;
  flex-wrap: wrap;
}
.masthead-title {
  font-family: "Playfair Display", "Georgia", serif;
  font-size: 2rem;
  font-weight: 700;
  letter-spacing: 0.02em;
  color: var(--gz-paper);
}
.masthead-title:hover {
  text-decoration: none;
  color: #fff;
}
.masthead-tagline {
  color: var(--gz-accent);
  font-style: italic;
  font-size: 0.95rem;
}
.site-nav {
  display: flex;
  gap: 18px;
  padding-top: 10px;
  align-items: center;
  font-size: 0.88rem;
  color: var(--gz-accent);
}
.site-nav a {
  color: var(--gz-paper);
}
.site-nav a:hover {
  color: #fff;
}
.nav-system {
  color: var(--gz-accent);
  font-family: "Menlo", monospace;
  font-size: 0.78rem;
  letter-spacing: 0.02em;
}
.nav-user {
  color: var(--gz-accent);
  margin-left: auto;
}
.nav-logout {
  color: var(--gz-paper);
}

/* Main layout */
.site-main {
  max-width: 1080px;
  margin: 0 auto;
  padding: 28px;
}

.page-title {
  font-family: "Playfair Display", "Georgia", serif;
  font-size: 2rem;
  color: var(--gz-purple-dark);
  margin: 0 0 6px 0;
}
.page-lede {
  color: var(--gz-muted);
  font-size: 1.02rem;
  margin-top: 0;
}

/* Login */
.login-shell {
  display: flex;
  justify-content: center;
  padding: 32px 0;
}
.login-card {
  width: 100%;
  max-width: 520px;
  background: #fff;
  border: 1px solid var(--gz-rule);
  border-top: 4px solid var(--gz-purple);
  padding: 28px 32px 24px 32px;
  box-shadow: 0 2px 4px rgba(45, 20, 55, 0.06);
}
.login-title {
  font-family: "Playfair Display", "Georgia", serif;
  font-size: 2rem;
  color: var(--gz-purple-dark);
  margin: 0 0 4px 0;
}
.login-sub {
  color: var(--gz-muted);
  margin: 0 0 16px 0;
}
.system-notice {
  background: var(--gz-warn-bg);
  border-left: 4px solid var(--gz-warn);
  padding: 10px 12px;
  font-size: 0.93rem;
  color: #5a3c00;
  margin-bottom: 18px;
}
.login-form {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-top: 14px;
}
.login-form label {
  display: flex;
  flex-direction: column;
  gap: 4px;
  font-size: 0.92rem;
}
.login-form input {
  font-family: inherit;
  font-size: 1rem;
  padding: 8px 10px;
  border: 1px solid var(--gz-rule);
  border-radius: 2px;
  background: #fff;
}
.login-form input:focus {
  outline: 2px solid var(--gz-purple-light);
  border-color: var(--gz-purple);
}
.login-form button {
  background: var(--gz-purple);
  color: #fff;
  padding: 10px;
  border: 0;
  font-size: 1rem;
  cursor: pointer;
  border-radius: 2px;
  font-weight: 600;
}
.login-form button:hover {
  background: var(--gz-purple-dark);
}
.login-error {
  color: var(--gz-error);
  background: var(--gz-error-bg);
  border-left: 4px solid var(--gz-error);
  padding: 8px 10px;
  font-size: 0.95rem;
}
.about-pressroom {
  margin-top: 18px;
  font-size: 0.92rem;
  color: var(--gz-muted);
}
.about-pressroom summary {
  cursor: pointer;
  color: var(--gz-purple-dark);
  font-weight: 600;
}

/* Dashboard */
.dashboard {
  display: grid;
  grid-template-columns: 2fr 1fr;
  gap: 28px;
  align-items: start;
}
.dashboard-main {
  min-width: 0;
}
.panel {
  background: #fff;
  border: 1px solid var(--gz-rule);
  padding: 18px 22px;
  margin-top: 18px;
}
.panel-head {
  display: flex;
  align-items: baseline;
  gap: 12px;
  border-bottom: 1px solid var(--gz-rule);
  padding-bottom: 6px;
  margin-bottom: 10px;
}
.panel-head h2 {
  font-family: "Playfair Display", "Georgia", serif;
  margin: 0;
  color: var(--gz-purple-dark);
  font-size: 1.3rem;
}
.panel-sub {
  color: var(--gz-muted);
  font-size: 0.88rem;
}
.panel-empty {
  color: var(--gz-muted);
  font-style: italic;
}
.panel-hint {
  background: #f5eef6;
  border: 1px solid var(--gz-accent);
}
.panel-hint h3 {
  color: var(--gz-purple-dark);
  margin-top: 0;
}
.panel-hint ul {
  margin: 0;
  padding-left: 18px;
}
.panel-hint li + li {
  margin-top: 4px;
}

.article-list {
  list-style: none;
  padding: 0;
  margin: 0;
}
.article-row {
  border-bottom: 1px dashed var(--gz-rule);
  padding: 10px 0;
}
.article-row:last-child { border-bottom: 0; }
.article-link {
  display: flex;
  gap: 8px;
  align-items: baseline;
  font-family: "Playfair Display", "Georgia", serif;
  color: var(--gz-purple-dark);
  font-size: 1.1rem;
}
.article-id {
  color: var(--gz-muted);
  font-family: "Menlo", monospace;
  font-size: 0.85rem;
}
.article-meta {
  display: inline-flex;
  gap: 6px;
  margin-left: 28px;
}
.article-teaser {
  color: var(--gz-muted);
  margin: 6px 0 0 28px;
  font-size: 0.95rem;
}

.pill {
  display: inline-block;
  padding: 1px 8px;
  font-size: 0.78rem;
  border-radius: 8px;
  font-family: "Menlo", monospace;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}
.pill-published { background: #e9f4e6; color: #24651e; }
.pill-draft { background: #fff3e0; color: #8a5a00; }
.pill-internal { background: #e9e3ec; color: var(--gz-purple-dark); }
.pill-muted { background: #efeaf0; color: var(--gz-muted); }
.pill-admin { background: #f5dff7; color: var(--gz-purple-dark); }
.pill-reporter { background: #e3edf5; color: #1b476b; }
.pill-contributor { background: #f0e9f2; color: var(--gz-purple); }
.pill-sysadmin { background: #e9e9e9; color: #555; }

.flash {
  border-radius: 2px;
  padding: 10px 12px;
  margin-top: 12px;
  font-size: 0.95rem;
}
.flash-warn {
  background: var(--gz-warn-bg);
  border-left: 4px solid var(--gz-warn);
  color: #5a3c00;
}

/* Newsroom sidebar */
.newsroom-sidebar {
  background: #fff;
  border: 1px solid var(--gz-rule);
  padding: 16px 18px;
  min-width: 0;
}
.sidebar-title {
  font-family: "Playfair Display", "Georgia", serif;
  color: var(--gz-purple-dark);
  font-size: 1.2rem;
  margin: 0 0 8px 0;
  border-bottom: 2px solid var(--gz-purple);
  padding-bottom: 4px;
}
.sidebar-feed {
  list-style: none;
  padding: 0;
  margin: 0;
}
.sidebar-feed li {
  padding: 10px 0;
  border-bottom: 1px dashed var(--gz-rule);
}
.sidebar-feed li:last-child { border-bottom: 0; }
.feed-kicker {
  display: block;
  font-family: "Menlo", monospace;
  text-transform: uppercase;
  color: var(--gz-purple);
  font-size: 0.72rem;
  letter-spacing: 0.08em;
}
.feed-headline {
  display: block;
  font-family: "Playfair Display", "Georgia", serif;
  color: var(--gz-ink);
  font-size: 1.02rem;
  line-height: 1.35;
  margin-top: 2px;
}
.feed-byline {
  color: var(--gz-muted);
  font-size: 0.82rem;
  font-style: italic;
}
.sidebar-note {
  margin-top: 12px;
  font-size: 0.85rem;
  color: var(--gz-muted);
  border-top: 1px dotted var(--gz-rule);
  padding-top: 8px;
  font-style: italic;
}

/* Article view */
.article-view {
  max-width: 720px;
  margin: 0 auto;
  background: #fff;
  border: 1px solid var(--gz-rule);
  padding: 28px 32px;
}
.article-topbar {
  display: flex;
  justify-content: space-between;
  font-size: 0.85rem;
  color: var(--gz-muted);
}
.back-link {
  font-family: "Menlo", monospace;
}
.article-id-tag {
  font-family: "Menlo", monospace;
  color: var(--gz-muted);
}
.article-headline {
  font-family: "Playfair Display", "Georgia", serif;
  font-size: 2.2rem;
  color: var(--gz-purple-dark);
  margin: 12px 0 4px 0;
  line-height: 1.15;
}
.article-byline {
  color: var(--gz-muted);
  font-size: 0.92rem;
  border-bottom: 1px solid var(--gz-rule);
  padding-bottom: 10px;
}
.article-body p {
  margin: 1em 0;
  font-size: 1.05rem;
  line-height: 1.7;
}
.article-footnote {
  margin-top: 18px;
  font-size: 0.82rem;
  color: var(--gz-muted);
  font-style: italic;
  border-top: 1px dotted var(--gz-rule);
  padding-top: 10px;
}

/* Admin */
.admin-shell {
  min-width: 0;
}
.admin-content {
  margin-top: 18px;
  background: #fff;
  border: 1px solid var(--gz-rule);
  padding: 20px 24px;
}
.admin-loading {
  font-style: italic;
  color: var(--gz-muted);
}
.admin-denied {
  background: var(--gz-error-bg);
  border-left: 4px solid var(--gz-error);
  padding: 12px 16px;
}
.admin-denied h2 {
  color: var(--gz-error);
  margin: 0 0 6px 0;
}
.admin-pane h2 {
  font-family: "Playfair Display", "Georgia", serif;
  color: var(--gz-purple-dark);
  margin: 0 0 6px 0;
}
.admin-stats ul { padding-left: 18px; }
.admin-users table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 8px;
  font-size: 0.93rem;
}
.admin-users th, .admin-users td {
  padding: 6px 8px;
  border-bottom: 1px dashed var(--gz-rule);
  text-align: left;
  font-family: "Menlo", monospace;
}
.admin-users th {
  background: #f5eef6;
  color: var(--gz-purple-dark);
}
.tool-list {
  list-style: none;
  padding: 0;
  margin: 0;
}
.tool-row {
  border: 1px solid var(--gz-rule);
  padding: 12px 14px;
  margin-top: 10px;
  background: #fbf7fc;
}
.tool-head {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
}
.tool-meta {
  font-family: "Menlo", monospace;
  color: var(--gz-muted);
  font-size: 0.82rem;
}
.tool-note {
  margin: 6px 0 0 0;
  font-size: 0.88rem;
  color: var(--gz-muted);
}
.muted { color: var(--gz-muted); }

/* Error page */
.error-shell {
  max-width: 640px;
  margin: 0 auto;
}
.error-card {
  background: #fff;
  border: 1px solid var(--gz-rule);
  border-left: 4px solid var(--gz-purple);
  padding: 22px 26px;
}
.error-title {
  color: var(--gz-purple-dark);
  font-family: "Playfair Display", "Georgia", serif;
  margin: 0 0 6px 0;
}
.error-message {
  color: var(--gz-muted);
}

/* Footer */
.site-footer {
  border-top: 1px solid var(--gz-rule);
  background: #f2ecf3;
  padding: 18px 28px;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  font-size: 0.88rem;
  color: var(--gz-muted);
  margin-top: 32px;
}
.footer-col strong { color: var(--gz-purple-dark); }
.footer-note { font-style: italic; }

@media (max-width: 820px) {
  .dashboard { grid-template-columns: 1fr; }
  .site-footer { grid-template-columns: 1fr; }
}

.system-notice-dev {
  background: #f3eef6;
  border-left: 4px solid var(--gz-purple);
  color: var(--gz-purple-dark);
}

.archive {
  background: #fff;
  border: 1px solid var(--gz-border);
  padding: 22px 26px;
  border-radius: 4px;
}
.archive-table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 14px;
  font-size: 0.95rem;
}
.archive-table th,
.archive-table td {
  text-align: left;
  padding: 10px 12px;
  border-bottom: 1px solid var(--gz-border);
  vertical-align: top;
}
.archive-table th {
  font-family: "Playfair Display", Georgia, serif;
  font-weight: 700;
  color: var(--gz-purple-dark);
  background: #faf7fb;
}
.archive-table td.archive-id,
.archive-table th.archive-id {
  color: var(--gz-muted);
  font-variant-numeric: tabular-nums;
  width: 68px;
}
.archive-table td.archive-title a {
  color: var(--gz-purple-dark);
  text-decoration: none;
  font-weight: 600;
}
.archive-table td.archive-title a:hover { text-decoration: underline; }
.archive-table td.archive-author { color: var(--gz-muted); }
.archive-table td.archive-category { color: var(--gz-muted); font-size: 0.9rem; }
"}

{"status": 200, "headers": {"Accept-Ranges": "bytes", "Content-Length": "3112", "Content-Type": "text/javascript; charset=utf-8", "Last-Modified": "Sat, 18 Apr 2026 12:26:50 GMT", "Date": "Tue, 28 Apr 2026 19:52:40 GMT"}, "body": "// PressRoom admin page client-side guard.
//
// DELIBERATELY VULNERABLE (OWASP A01:2021):
// The admin area is protected only in the browser. The server does NOT
// enforce the admin role on /api/admin/* routes. Any authenticated user can
// call the underlying API endpoints directly, for example with curl.

(function () {
  var content = document.getElementById('admin-content');
  if (!content) {
    return;
  }

  function renderAccessDenied() {
    content.innerHTML = ''
      + '<div class="admin-denied">'
      + '<h2>Access denied</h2>'
      + '<p>PressRoom: Access denied. This section requires editorial clearance.</p>'
      + '<p class="muted">Redirecting you back to the dashboard.</p>'
      + '</div>';
    setTimeout(function () {
      window.location = '/dashboard?error=admin_required';
    }, 1800);
  }

  function renderAdmin(user, data) {
    var tools = (data.maintenance_tools || []).map(function (t) {
      return ''
        + '<li class="tool-row">'
        + '<div class="tool-head"><strong>' + t.name + '</strong> '
        + '<span class="tool-meta">' + t.method + ' ' + t.endpoint + '</span></div>'
        + '<pre class="tool-body">' + t.body + '</pre>'
        + '<p class="tool-note">' + t.note + ' (added by <em>' + t.added_by + '</em>)</p>'
        + '</li>';
    }).join('');

    var users = (data.users || []).map(function (u) {
      return '<tr>'
        + '<td>' + u.username + '</td>'
        + '<td>' + u.display_name + '</td>'
        + '<td><span class="pill pill-' + u.role + '">' + u.role + '</span></td>'
        + '<td>' + (u.active ? 'active' : 'disabled') + '</td>'
        + '</tr>';
    }).join('');

    content.innerHTML = ''
      + '<div class="admin-pane">'
      + '<h2>Editor-in-chief dashboard</h2>'
      + '<p>Signed in as <strong>' + user.display_name + '</strong> (' + user.username + ').</p>'
      + '<section class="admin-stats"><h3>Newsroom stats</h3>'
      + '<ul>'
      + '<li>Users total: ' + data.stats.users_total + '</li>'
      + '<li>Articles total: ' + data.stats.articles_total + '</li>'
      + '<li>Drafts in flight: ' + data.stats.drafts_in_flight + '</li>'
      + '<li>Published this week: ' + data.stats.published_this_wk + '</li>'
      + '</ul></section>'
      + '<section class="admin-users"><h3>User directory</h3>'
      + '<table><thead><tr><th>username</th><th>display name</th><th>role</th><th>status</th></tr></thead>'
      + '<tbody>' + users + '</tbody></table></section>'
      + '<section class="admin-tools"><h3>Maintenance tools</h3>'
      + '<ul class="tool-list">' + tools + '</ul></section>'
      + '</div>';
  }

  fetch('/api/me', { credentials: 'same-origin' })
    .then(function (r) { return r.json(); })
    .then(function (user) {
      if (!user || user.role !== 'admin') {
        renderAccessDenied();
        return;
      }
      return fetch('/api/admin/dashboard', { credentials: 'same-origin' })
        .then(function (r) { return r.json(); })
        .then(function (data) { renderAdmin(user, data); });
    })
    .catch(function () {
      renderAccessDenied();
    });
}());
"}
